        parsed,
        converters,
        aliases=aliases,
        strict=strict,
    )


def validate(
    parsed: Mapping[str, Any],
    validators: Mapping[str, Callable[[Any], bool]],
    *,
    aliases: bool = True,
    strict: bool = False,
) -> "ParsedOptions":
    """Validate parsed values with explicit per-key predicates."""

    validated = ParsedOptions(parsed.items())
    alias_map = {normalize_key(key): key for key in parsed} if aliases else {}
    for key, validator in validators.items():
        target = key if key in validated else alias_map.get(key)
        if target is None:
            if strict:
                raise KeyError(key)
            continue
        value = validated[target]
        try:
            is_valid = validator(value)
        except Exception as exc:
            raise ConversionError(f"Validation failed for {target!r}: {exc}") from exc
        if not is_valid:
            raise ConversionError(f"Validation failed for {target!r}: {value!r}")
    return validated


class ParsedOptions(dict[str, Any]):
    def __repr__(self) -> str:
        return "{%s}" % ",\n ".join("%r: %r" % i for i in sorted(self.items()))

    def __getattr__(self, name: str) -> str | bool | int | list[str] | None:
        if name in self:
            return self[name]
        for key, value in self.items():
            if name in {key, normalize_key(key), key.lstrip("<").rstrip(">")}:
                return value
        return None

    def as_kwargs(self) -> dict[str, Any]:
        """Return the mapping with Python-friendly normalized keys."""
        return {normalize_key(key): value for key, value in self.items()}
